 id TEXT PRIMARY KEY, document_id TEXT NOT NULL, project_id TEXT NOT NULL, parent_id TEXT NOT NULL,
 created_by TEXT NOT NULL REFERENCES users(id), created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),
 FOREIGN KEY(document_id,project_id) REFERENCES documents(id,project_id), FOREIGN KEY(parent_id,project_id) REFERENCES cancellations(id,project_id), UNIQUE(document_id,parent_id)
) STRICT;
CREATE INDEX document_cancellation_links_parent ON document_cancellation_links(parent_id,document_id);
CREATE TRIGGER document_cancellation_links_classification BEFORE INSERT ON document_cancellation_links
WHEN NOT EXISTS (SELECT 1 FROM documents WHERE id=NEW.document_id AND project_id=NEW.project_id AND (classification='restricted' OR classification='financial'))
BEGIN SELECT RAISE(ABORT,'document classification must cover parent'); END;
CREATE TRIGGER document_cancellation_links_immutable_update BEFORE UPDATE ON document_cancellation_links BEGIN SELECT RAISE(ABORT,'document evidence link is immutable'); END;
CREATE TRIGGER document_cancellation_links_immutable_delete BEFORE DELETE ON document_cancellation_links BEGIN SELECT RAISE(ABORT,'document evidence link is retained'); END;
