CREATE TRIGGER document_scope_immutable BEFORE UPDATE OF project_id,classification ON documents
WHEN (NEW.project_id IS NOT OLD.project_id OR NEW.classification IS NOT OLD.classification) AND EXISTS(SELECT 1 FROM document_links WHERE document_id=OLD.id)
BEGIN SELECT RAISE(ABORT,'linked document scope and classification are immutable'); END;
CREATE TRIGGER document_parent_registry_update BEFORE UPDATE ON document_parent_types BEGIN SELECT RAISE(ABORT,'parent registry is migration-owned'); END;
CREATE TRIGGER document_parent_registry_delete BEFORE DELETE ON document_parent_types BEGIN SELECT RAISE(ABORT,'parent registry is migration-owned'); END;
